INSERT INTO historical_figures (id, clan_id, branch_id, name, name_hanja, category, title_achievement, period, birth_year, death_year, honor, basis, image_url, verified, source) VALUES
  (1, 1, 2, '이종무', '李從茂', 'historical', '왜구를 여러 차례 격퇴하고 세종 즉위 초 대마도 정벌을 이끈 무신. 시호 양후(襄厚)로 양후공파의 파조가 되었다.', '고려 말~조선 초', 1360, 1425, NULL, NULL, NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (5, 1, NULL, '이임간', '李林幹', 'historical', '고려 충선왕 대 문하시중 평장사에 올라 장천부원군에 봉해졌다. 장수 이씨의 시조.', '고려 후기', NULL, NULL, NULL, NULL, NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (6, 1, 1, '이종화', '李從華', 'historical', '이종무의 형. 태조 대 과거에 급제해 사간원 정언을 지냈고 정언공파의 파조가 되었다.', '조선 초', NULL, NULL, NULL, NULL, NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (2, 2, NULL, '조준', '趙浚', 'historical', '조선 개국 1등공신. 과전법 등 토지개혁을 주도했고 평양부원군에 봉해졌다.', '고려 말~조선 초', 1346, 1405, NULL, NULL, NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (3, 2, NULL, '조인규', '趙仁規', 'historical', '고려 후기 몽골어 역관 출신으로 재상에 올라 평양 조씨를 명문으로 일으켰다. 조준의 증조부.', '고려 후기', NULL, NULL, NULL, NULL, NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (7, 2, NULL, '조견', '趙狷', 'historical', '조준의 동생. 개국공신에 책록되었으나 고려에 대한 절의를 지키려 사양했다고 전한다.', '고려 말~조선 초', 1351, 1425, NULL, NULL, NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (30, 3, NULL, '이완용', '李完用', 'collaborator', '학부대신으로 을사늑약(1905)에 찬성했고, 총리대신으로 한일병합조약(1910)을 체결했다.', '대한제국~일제강점기', 1858, 1926, NULL, '을사오적. 친일반민족행위진상규명위원회 2006년 결정(106인 명단)', NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (36, 3, NULL, '이윤용', '李潤用', 'collaborator', '이완용의 이복형. 대한제국 군부대신 등을 지냈고 병합 후 조선귀족 남작 작위를 받았다.', '대한제국~일제강점기', NULL, NULL, NULL, '친일반민족행위진상규명위원회 친일반민족행위자 결정', NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (20, 3, NULL, '이재', '李縡', 'historical', '호는 도암. 숙종~영조 대의 성리학자로 대제학을 지냈다.', '조선 후기', NULL, NULL, NULL, NULL, NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (31, 4, NULL, '박제순', '朴齊純', 'collaborator', '외부대신으로 을사늑약에 서명했다.', '대한제국~일제강점기', 1858, 1916, NULL, '을사오적. 친일반민족행위진상규명위원회 2006년 결정(106인 명단)', NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (21, 4, NULL, '박세당', '朴世堂', 'historical', '숙종 대의 학자. 주자 해석에 얽매이지 않는 경전 주석으로 사문난적 논란을 겪었다.', '조선 후기', NULL, NULL, NULL, NULL, NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (22, 4, NULL, '박지원', '朴趾源', 'historical', '호는 연암. 『열하일기』를 쓴 북학파 실학자.', '조선 후기', 1737, 1805, NULL, NULL, NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (23, 4, NULL, '박규수', '朴珪壽', 'historical', '박지원의 손자. 개화사상의 선구자로 김옥균 등 개화파를 길러냈다.', '조선 말기', 1807, 1877, NULL, NULL, NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (24, 5, NULL, '이성계', '李成桂', 'historical', '조선을 건국한 태조.', '고려 말~조선 초', 1335, 1408, NULL, NULL, NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (25, 5, NULL, '세종(이도)', '李祹', 'historical', '조선 제4대 국왕. 훈민정음을 창제했다.', '조선 전기', 1397, 1450, NULL, NULL, NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (17, 5, NULL, '이봉창', '李奉昌', 'independence', '한인애국단 단원. 1932년 도쿄에서 일왕 행렬에 폭탄을 던졌다.', '일제강점기', NULL, 1932, '건국훈장 대한민국장', NULL, NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (32, 5, NULL, '이근택', '李根澤', 'collaborator', '군부대신으로 을사늑약에 찬성했다.', '대한제국~일제강점기', NULL, NULL, NULL, '을사오적. 친일반민족행위진상규명위원회 2006년 결정(106인 명단)', NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (33, 5, NULL, '이지용', '李址鎔', 'collaborator', '내부대신으로 을사늑약에 찬성했다.', '대한제국~일제강점기', NULL, NULL, NULL, '을사오적. 친일반민족행위진상규명위원회 2007년 결정(195인 명단)', NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (26, 6, NULL, '권근', '權近', 'historical', '여말선초의 성리학자이자 조선 개국공신. 안동 권씨가 조선의 명문으로 자리 잡는 기반을 닦았다.', '고려 말~조선 초', 1352, 1409, NULL, NULL, NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (27, 6, NULL, '권율', '權慄', 'historical', '임진왜란 때 행주대첩을 승리로 이끈 도원수. 권근의 6대손.', '조선 중기', 1537, 1599, NULL, NULL, NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (34, 6, NULL, '권중현', '權重顯', 'collaborator', '농상공부대신으로 을사늑약에 찬성했다.', '대한제국~일제강점기', NULL, NULL, NULL, '을사오적. 친일반민족행위진상규명위원회 2006년 결정(106인 명단)', NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (28, 7, NULL, '송시열', '宋時烈', 'historical', '노론의 영수. 좌의정을 지냈고 문묘와 종묘에 배향되었다.', '조선 후기', 1607, 1689, NULL, NULL, NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (29, 7, NULL, '송준길', '宋浚吉', 'historical', '송시열과 함께 "양송"으로 불린 성리학자. 문묘에 배향되었다.', '조선 후기', 1606, 1672, NULL, NULL, NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (35, 7, NULL, '송병준', '宋秉畯', 'collaborator', '일진회를 이끌며 한일병합을 적극 추진했다. 은진 송씨라는 계보 문헌 근거는 확인되지 않는다는 지적이 있다.', '대한제국~일제강점기', 1858, 1925, NULL, '친일반민족행위진상규명위원회 2007년 결정(195인 명단)', NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (40, 8, NULL, '안향', '安珦', 'historical', '고려에 성리학을 처음 들여온 학자. 시조 안자미의 증손.', '고려 후기', 1243, 1306, NULL, NULL, NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (10, 8, NULL, '안중근', '安重根', 'independence', '1909년 하얼빈역에서 이토 히로부미를 처단했다. 옥중에서 「동양평화론」을 집필.', '대한제국', 1879, 1910, '건국훈장 대한민국장', NULL, NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (11, 8, NULL, '안창호', '安昌浩', 'independence', '신민회·흥사단을 조직하고 대한민국 임시정부에 참여한 독립운동가·교육자.', '대한제국~일제강점기', 1878, 1938, '건국훈장 대한민국장', NULL, NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
  (41, 9, NULL, '윤관', '尹瓘', 'historical', '17만 대군으로 여진을 정벌하고 동북 9성을 쌓았다. 파평 윤씨의 중시조.', '고려 중기', NULL, NULL, NULL, NULL, NULL, true, '공개 백과 자료 (위키백과·한국민족문화대백과)'),
